function Dashboard() {
  const navigate = useNavigate();
  const {
    outreachActivities = [],
    userProfile,
    positions = [],
    pipeline = [],
    recruiters = [],
    loading: dataContextLoading
  } = useData();
  const [activeTab, setActiveTab] = useState(null); // Default to null for Welcome Screen
  const [pipelineMetrics, setPipelineMetrics] = useState({});
  const [executiveStats, setExecutiveStats] = useState({});
  const [roleHealth, setRoleHealth] = useState({});
  const [historicalData, setHistoricalData] = useState([]);
  const [recruiterStats, setRecruiterStats] = useState([]);
  const [callsData, setCallsData] = useState({ today: [], week: [] });
  const [interviewsData, setInterviewsData] = useState({ today: [], week: [] });
  const [groupedRolesByHealth, setGroupedRolesByHealth] = useState({ Healthy: [], Warning: [], Critical: [] }); // New state
  const [weeklyOutreachByPosition, setWeeklyOutreachByPosition] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchAllData = useCallback(async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchPipelineMetrics(),
        fetchExecutiveStats(),
        fetchHistoricalData(),
        fetchRecruiterStats(),
        fetchCallsAndInterviews(),
        fetchWeeklyOutreachByPosition()
      ]);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  }, [userProfile, positions, pipeline, recruiters, outreachActivities]);

  useEffect(() => {
    if (!dataContextLoading) {
      fetchAllData();
    }
  }, [dataContextLoading, fetchAllData]);

  async function fetchPipelineMetrics() {
    const { data, error } = await supabase
      .from('pipeline')
      .select('*, positions!inner(*, clients(company_name)), candidates(name)')
      .neq('stage', 'Archived')
      .eq('positions.status', 'Open');

    if (error || !data) {
      setPipelineMetrics({});
      return;
    }

    const grouped = data.reduce((acc, item) => {
      const posId = item?.position_id;
      if (!posId) return acc;

      if (!acc[posId]) {
        acc[posId] = {
          title: item?.positions?.title || 'Unknown Position',
          company: item?.positions?.clients?.company_name || 'N/A',
          count: 0,
          stages: { 'Screening': 0, 'Submit to Client': 0, 'Interview 1': 0, 'Interview 2': 0, 'Interview 3': 0, 'Offer': 0, 'Hired': 0 }
        };
      }

      const stage = item.stage;
      if (stage && stage in acc[posId].stages) {
        acc[posId].stages[stage]++;
      }
      acc[posId].count++;
      return acc;
    }, {});

    setPipelineMetrics(grouped);
    await calculateRoleHealth(grouped, data);
  }

  async function calculateRoleHealth(metrics, pipelineData) {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    const fourteenDaysAgo = new Date();
    fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14);

    const positionIds = Object.keys(metrics);
    if (positionIds.length === 0) {
      setRoleHealth({});
      // Update rolesNeedingAttention count based on health data
      setExecutiveStats(prev => ({
        ...prev,
        rolesNeedingAttention: 0
      }));
      return;
    }

    const { data: outreachData } = await supabase
      .from('recruiter_outreach')
      .select('position_id, activity_status, created_at')
      .in('position_id', positionIds)
      .gte('created_at', fourteenDaysAgo.toISOString());

    const healthMap = {};
    const replyStatuses = ['reply_received', 'accepted', 'call_scheduled', 'declined', 'ready_for_submission'];

    for (const [posId, data] of Object.entries(metrics)) {
      const positionOutreach = outreachData?.filter(o => o.position_id === posId) || [];
      const recentOutreach = positionOutreach.filter(o => new Date(o.created_at) >= sevenDaysAgo);
      const replies = positionOutreach.filter(o => replyStatuses.includes(o.activity_status)).length;
      const replyRate = positionOutreach.length > 0 ? parseFloat(((replies / positionOutreach.length) * 100).toFixed(1)) : 0;

      const positionPipeline = pipelineData?.filter(p => p.position_id === posId) || [];
      let lastActivityDate = new Date(0);

      lastActivityDate = positionPipeline.reduce((latest, p) => {
        const itemTimestamp = p.updated_at || p.created_at;
        if (!itemTimestamp) return latest;
        const itemDate = new Date(itemTimestamp);
        return !isNaN(itemDate) && itemDate > latest ? itemDate : latest;
      }, lastActivityDate);

      const daysSinceActivity = lastActivityDate.getTime() > 0 ? calculateDaysDifference(lastActivityDate.toISOString()) : Infinity;

      let health = 'healthy';
      const hasOutreach = positionOutreach.length > 0;
      if (daysSinceActivity > 14 || (hasOutreach && recentOutreach.length === 0) || (hasOutreach && replyRate < 10)) {
        health = 'critical';
      } else if (daysSinceActivity > 7 || (hasOutreach && recentOutreach.length < 5) || (hasOutreach && replyRate < 20)) {
        health = 'warning';
      }

      healthMap[posId] = {
        title: data?.title || 'Unknown Title',
        health,
        outreach: recentOutreach.length,
        replyRate: replyRate,
        daysSinceActivity: daysSinceActivity === Infinity ? 'N/A' : daysSinceActivity
      };
    }

    setRoleHealth(healthMap);

    // Calculate and update rolesNeedingAttention count based on health data
    const rolesNeedingAttentionCount = Object.values(healthMap).filter(
      role => role.health === 'critical' || role.health === 'warning'
    ).length;

    console.log('📊 Roles Health Data:', healthMap);
    console.log('📊 Roles Needing Attention Count:', rolesNeedingAttentionCount);

    setExecutiveStats(prev => ({
      ...prev,
      rolesNeedingAttention: rolesNeedingAttentionCount
    }));

    // Group roles by health status for the tooltip
    const groupedRoles = {
      Healthy: [],
      Warning: [],
      Critical: [],
    };
    Object.values(healthMap).forEach(role => {
      if (groupedRoles[role.health]) {
        groupedRoles[role.health].push(role.title);
      }
    });
    console.log('--- DEBUG: calculateRoleHealth - groupedRoles before setting state:', groupedRoles); // New log
    setGroupedRolesByHealth(groupedRoles); // Set the new state
  }

  async function fetchExecutiveStats() {
    // Correctly define the current week (Sunday to Saturday)
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const dayOfWeek = today.getDay(); // 0=Sunday, 1=Monday, etc.
    const startOfWeek = new Date(today);
    startOfWeek.setDate(today.getDate() - dayOfWeek);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 7);

    const results = await Promise.allSettled([
      supabase.from('pipeline').select('id', { count: 'exact', head: true }).in('stage', ['Offer', 'Interview 3']).eq('status', 'Active'),
      supabase.from('pipeline').select('id', { count: 'exact', head: true }).eq('stage', 'Submit to Client').gte('created_at', startOfWeek.toISOString()),
      supabase.from('pipeline').select('id, positions!inner(status)', { count: 'exact' }).eq('status', 'Active').neq('stage', 'Archived').neq('stage', 'Hired').eq('positions.status', 'Open'),
      supabase.from('recruiter_outreach').select('activity_status', { count: 'exact' }).gte('created_at', startOfWeek.toISOString()),
      supabase.from('interviews').select('id', { count: 'exact', head: true }).gte('interview_date', today.toISOString()).lte('interview_date', endOfWeek.toISOString())
    ]);

    console.log('📊 Dashboard Query Results:', results);

    const getCount = (index) => {
      const response = results[index];
      if (response.status === 'rejected') {
        console.log(`❌ Query ${index} rejected:`, response.reason);
        return 0;
      }
      const count = response.value.count ?? 0;
      console.log(`✅ Query ${index} count:`, count);
      return count;
    };

    const outreachCount = getCount(3);
    const replyStatuses = ['reply_received', 'accepted', 'call_scheduled', 'declined', 'ready_for_submission'];

    // Query for ALL outreach that has had activity (replies) this week
    const { data: repliesThisWeek } = await supabase
      .from('recruiter_outreach')
      .select('activity_status')
      .in('activity_status', replyStatuses)
      .gte('last_activity', startOfWeek.toISOString());

    const replies = repliesThisWeek?.length || 0;
    // If no outreach sent this week, don't calculate percentage
    const replyRate = outreachCount > 0 ? parseFloat(((replies / outreachCount) * 100).toFixed(1)) : null;
    const repliesReceived = replies; // Store raw count for display

    const stats = {
      rolesNeedingAttention: 0, // Will be updated by calculateRoleHealth() based on critical/warning roles
      closeToHiring: getCount(0),
      interviewsThisWeek: getCount(4),
      submissionsThisWeek: getCount(1),
      activeCandidates: getCount(2),
      outreachThisWeek: outreachCount,
      replyRate: replyRate,
      repliesReceived: repliesReceived // NEW: Raw count of replies received
    };

    console.log('📈 Final Executive Stats:', stats);
    setExecutiveStats(stats);
  }

  async function fetchHistoricalData() {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const dayStart = new Date(date.setHours(0, 0, 0, 0)).toISOString();
      const dayEnd = new Date(date.setHours(23, 59, 59, 999)).toISOString();

      const { data: outreach } = await supabase
        .from('recruiter_outreach')
        .select('id')
        .gte('created_at', dayStart)
        .lte('created_at', dayEnd);

      const { data: submissions } = await supabase
        .from('pipeline')
        .select('id')
        .eq('stage', 'Submit to Client')
        .gte('created_at', dayStart)
        .lte('created_at', dayEnd);

      days.push({
        day: date.toLocaleDateString('en-US', { weekday: 'short' }),
        outreach: outreach?.length || 0,
        submissions: submissions?.length || 0
      });
    }

    setHistoricalData(days);
  }

  async function fetchRecruiterStats() {
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const dayOfWeek = today.getDay(); // 0=Sunday
    const startOfWeek = new Date(today);
    startOfWeek.setDate(today.getDate() - dayOfWeek);

    // Outreach sent this week
    const { data: outreachData } = await supabase
      .from('recruiter_outreach')
      .select('recruiter_id, recruiters(name, role)')
      .gte('created_at', startOfWeek.toISOString());

    // Replies received this week (regardless of when outreach was sent)
    const { data: repliesData } = await supabase
      .from('recruiter_outreach')
      .select('recruiter_id, activity_status')
      .in('activity_status', ['reply_received', 'accepted', 'call_scheduled', 'declined', 'ready_for_submission'])
      .gte('last_activity', startOfWeek.toISOString());

    const { data: pipelineData } = await supabase
      .from('pipeline')
      .select('recruiter_id, stage, created_at')
      .eq('stage', 'Screening')
      .gte('created_at', startOfWeek.toISOString());

    const breakdownMap = {};

    recruiters.forEach(r => {
      const role = r?.role?.toLowerCase() || '';
      if (r?.id && role !== 'director' && !role.includes('manager')) {
        breakdownMap[r.id] = { id: r.id, name: r.name, totalOutreach: 0, replies: 0, internalSubmissions: 0, replyRate: 0 };
      }
    });

    outreachData?.forEach(o => {
      if (breakdownMap[o.recruiter_id]) {
        breakdownMap[o.recruiter_id].totalOutreach++;
      }
    });

    repliesData?.forEach(o => {
      if (breakdownMap[o.recruiter_id]) {
        breakdownMap[o.recruiter_id].replies++;
      }
    });

    pipelineData?.forEach(p => {
      if (breakdownMap[p.recruiter_id]) {
        breakdownMap[p.recruiter_id].internalSubmissions++;
      }
    });

    const stats = Object.values(breakdownMap).map(rec => {
      rec.replyRate = rec.totalOutreach > 0 ? parseFloat(((rec.replies / rec.totalOutreach) * 100).toFixed(1)) : 0;
      return rec;
    });

    setRecruiterStats(stats);
  }

  async function fetchCallsAndInterviews() {
    // Use local timezone to match user's actual "today"
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
    const endOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
    const endOfWeek = new Date(today);
    endOfWeek.setDate(today.getDate() + 7);

    // Fetch calls
    const { data: allCalls } = await supabase
      .from('recruiter_outreach')
      .select('*, positions(title), recruiters(name)')
      .eq('activity_status', 'call_scheduled')
      .not('scheduled_call_date', 'is', null)
      .gte('scheduled_call_date', today.toISOString())
      .lte('scheduled_call_date', endOfWeek.toISOString())
      .order('scheduled_call_date', { ascending: true });

    const callsToday = allCalls?.filter(c => {
      const callDate = new Date(c.scheduled_call_date);
      return callDate >= today && callDate <= endOfToday;
    }) || [];

    const callsWeek = allCalls?.filter(c => {
      const callDate = new Date(c.scheduled_call_date);
      return callDate > endOfToday && callDate <= endOfWeek;
    }) || [];

    // Fetch interviews - Fixed to match correct schema (no recruiters FK)
    const { data: allInterviews, error: interviewError } = await supabase
      .from('interviews')
      .select('*, candidates(name, email), positions(title, clients(company_name))')
      .gte('interview_date', today.toISOString())
      .lte('interview_date', endOfWeek.toISOString())
      .order('interview_date', { ascending: true });

    console.log('📅 Interview Query Debug:', {
      today: today.toISOString(),
      endOfWeek: endOfWeek.toISOString(),
      allInterviews,
      error: interviewError
    });

    // Interviews Today - Shows interviews happening today only (verified pattern matches callsToday)
    const interviewsToday = allInterviews?.filter(i => {
      const interviewDate = new Date(i.interview_date);
      return interviewDate >= today && interviewDate <= endOfToday;
    }) || [];

    // Interviews This Week - Shows ALL interviews from today through next 7 days (FIXED: changed from > endOfToday to >= today)
    const interviewsWeek = allInterviews?.filter(i => {
      const interviewDate = new Date(i.interview_date);
      return interviewDate >= today && interviewDate <= endOfWeek;
    }) || [];

    console.log('📅 Filtered Interviews:', {
      today: interviewsToday.length,
      week: interviewsWeek.length,
      todayData: interviewsToday,
      weekData: interviewsWeek
    });

    setCallsData({ today: callsToday, week: callsWeek });
    setInterviewsData({ today: interviewsToday, week: interviewsWeek });
  }

  async function fetchWeeklyOutreachByPosition() {
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const dayOfWeek = today.getDay(); // 0=Sunday
    const startOfWeek = new Date(today);
    startOfWeek.setDate(today.getDate() - dayOfWeek);

    const { data: outreachData, error } = await supabase
      .from('recruiter_outreach')
      .select('position_id, positions!inner(title)')
      .gte('created_at', startOfWeek.toISOString())
      .eq('positions.status', 'Open');

    if (error || !outreachData) {
      console.error('Error fetching weekly outreach by position:', error);
      setWeeklyOutreachByPosition([]);
      return;
    }

    const outreachByPosition = outreachData.reduce((acc, outreach) => {
      if (outreach.positions) {
        const positionTitle = outreach.positions.title;
        acc[positionTitle] = (acc[positionTitle] || 0) + 1;
      }
      return acc;
    }, {});

    const formattedData = Object.entries(outreachByPosition)
      .map(([title, count]) => ({ title, count }))
      .sort((a, b) => b.count - a.count);

    setWeeklyOutreachByPosition(formattedData);
  }

  // =========================================================================
  // TOOLTIP DATA GENERATORS
  // =========================================================================
  const getRolesNeedingAttentionTooltip = useMemo(() => {
    if (!roleHealth || Object.keys(roleHealth).length === 0) return [];

    const criticalAndWarning = Object.entries(roleHealth)
      .filter(([_, health]) => health.health === 'critical' || health.health === 'warning')
      .sort((a, b) => {
        const order = { critical: 0, warning: 1 };
        return order[a[1].health] - order[b[1].health];
      })
      .slice(0, 6);

    console.log('📊 Tooltip - Critical/Warning Roles:', criticalAndWarning.length);

    const items = criticalAndWarning.map(([posId, health]) => ({
      primary: health.title,
      secondary: `${health.outreach} outreach last 7 days • ${health.replyRate}% reply rate`,
      badge: health.health === 'critical' ? 'Critical' : 'Warning',
      badgeClass: health.health === 'critical' ? 'badge-critical' : 'badge-warning'
    }));

    const totalCriticalWarning = Object.entries(roleHealth).filter(
      ([_, health]) => health.health === 'critical' || health.health === 'warning'
    ).length;

    if (totalCriticalWarning > 6) {
      items.push({
        primary: `and ${totalCriticalWarning - 6} more roles...`,
        secondary: null
      });
    }

    console.log('📊 Tooltip Data Items:', items);

    return items.length > 0 ? items : [{ primary: 'All roles are healthy!', secondary: 'Great job!' }];
  }, [roleHealth]);

  const getCloseToHiringTooltip = useMemo(() => {
    if (!pipeline || pipeline.length === 0) return [];

    const closeToHire = pipeline
      .filter(p => (p.stage === 'Offer' || p.stage === 'Interview 3') && p.status === 'Active')
      .slice(0, 6);

    const items = closeToHire.map(p => {
      const positionTitle = positions.find(pos => pos.id === p.position_id)?.title || 'Unknown Position';
      return {
        primary: p.candidates?.name || 'Unknown Candidate',
        secondary: `${positionTitle} • ${p.stage}`,
        badge: p.stage === 'Offer' ? '🎯' : '📋'
      };
    });

    if (pipeline.filter(p => (p.stage === 'Offer' || p.stage === 'Interview 3') && p.status === 'Active').length > 6) {
      items.push({
        primary: `and ${pipeline.filter(p => (p.stage === 'Offer' || p.stage === 'Interview 3') && p.status === 'Active').length - 6} more...`,
        secondary: null
      });
    }

    return items.length > 0 ? items : [{ primary: 'No candidates in final stages', secondary: 'Focus on pipeline progression' }];
  }, [pipeline, positions]);

  const getInterviewsThisWeekTooltip = useMemo(() => {
    if (!interviewsData.week || interviewsData.week.length === 0) return [];

    const items = interviewsData.week.slice(0, 6).map(interview => ({
      primary: interview.candidates?.name || 'Unknown Candidate',
      secondary: `${interview.positions?.title || 'Unknown Position'} • ${new Date(interview.interview_date).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}`,
      badge: new Date(interview.interview_date).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
    }));

    if (interviewsData.week.length > 6) {
      items.push({
        primary: `and ${interviewsData.week.length - 6} more interviews...`,
        secondary: null
      });
    }

    return items.length > 0 ? items : [{ primary: 'No interviews scheduled', secondary: 'Schedule interviews for active candidates' }];
  }, [interviewsData]);

  const getSubmissionsThisWeekTooltip = useMemo(() => {
    if (!pipeline || pipeline.length === 0) return [];

    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const dayOfWeek = today.getDay(); // 0=Sunday
    const startOfWeek = new Date(today);
    startOfWeek.setDate(today.getDate() - dayOfWeek);

    const recentSubmissions = pipeline
      .filter(p => p.stage === 'Submit to Client' && new Date(p.created_at) >= startOfWeek)
      .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
      .slice(0, 6);

    const items = recentSubmissions.map(p => {
      const positionTitle = positions.find(pos => pos.id === p.position_id)?.title || 'Unknown Position';
      return {
        primary: p.candidates?.name || 'Unknown Candidate',
        secondary: `${positionTitle}`,
        badge: new Date(p.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
      };
    });

    if (pipeline.filter(p => p.stage === 'Submit to Client' && new Date(p.created_at) >= startOfWeek).length > 6) {
      items.push({
        primary: `and ${pipeline.filter(p => p.stage === 'Submit to Client' && new Date(p.created_at) >= startOfWeek).length - 6} more...`,
        secondary: null
      });
    }

    return items.length > 0 ? items : [{ primary: 'No recent submissions', secondary: 'Move qualified candidates to client submission' }];
  }, [pipeline, positions]);

  const getActiveCandidatesTooltip = useMemo(() => {
    if (!pipelineMetrics || Object.keys(pipelineMetrics).length === 0) return [];

    const topRoles = Object.entries(pipelineMetrics)
      .sort((a, b) => b[1].count - a[1].count)
      .slice(0, 6);

    const items = topRoles.map(([posId, data]) => ({
      primary: data.title,
      secondary: `${data.company}`,
      badge: `${data.count} candidates`
    }));

    if (Object.keys(pipelineMetrics).length > 6) {
      items.push({
        primary: `and ${Object.keys(pipelineMetrics).length - 6} more roles...`,
        secondary: null
      });
    }

    return items.length > 0 ? items : [{ primary: 'No active candidates', secondary: 'Start recruiting for open positions' }];
  }, [pipelineMetrics]);

  const getTeamOutreachTooltip = useMemo(() => {
    if (!recruiterStats || recruiterStats.length === 0) return [];

    const topRecruiters = [...recruiterStats]
      .sort((a, b) => b.totalOutreach - a.totalOutreach)
      .slice(0, 6);

    const items = topRecruiters.map(rec => ({
      primary: rec.name,
      secondary: `${rec.replies} replies • ${rec.internalSubmissions || 0} screened`,
      badge: `${rec.totalOutreach} sent`,
      badgeClass: rec.replyRate >= 35 ? 'badge-success' : rec.replyRate >= 20 ? 'badge-warning' : 'badge-critical'
    }));

    if (recruiterStats.length > 6) {
      items.push({
        primary: `and ${recruiterStats.length - 6} more recruiters...`,
        secondary: null
      });
    }

    return items.length > 0 ? items : [{ primary: 'No outreach data', secondary: 'Encourage team to send outreach messages' }];
  }, [recruiterStats]);

  if (loading) {
    return (
      <div className="dashboard-container">
        <div className="loading-state">
          <Activity size={48} className="spinning" />
          <p>Loading your command center...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      {/* Header */}
      <motion.div
        className="page-header"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
      >
        <div className="header-content">
          <h1>Command Center</h1>

          <p>Welcome back, {userProfile?.name || 'Manager'}! Here's your recruitment empire.</p>
        </div>
        <div className="header-actions">
          <div className="mini-stat">
            <Clock size={16} />
            <span>Live Data</span>
          </div>
        </div>
      </motion.div>

      {/* Tab Navigation */}
      <TabNavigation activeTab={activeTab} setActiveTab={setActiveTab} />

      {/* Welcome Screen (Default State) */}
      {!activeTab && <WelcomeScreen />}

      {/* Tab Content */}
      {activeTab === 'overview' && (
        <div>
          {/* Metrics Grid */}
          <div className="metrics-grid">
            <AnimatedMetricCard
              icon={AlertTriangle}
              value={executiveStats.rolesNeedingAttention || 0}
              label="Roles Need Attention"
              color="#F7A9BA"
              tooltipItems={getRolesNeedingAttentionTooltip}
            />
            <AnimatedMetricCard
              icon={Target}
              value={executiveStats.closeToHiring || 0}
              label="Close to Hiring"
              color="#B8D4D0"
              tooltipItems={getCloseToHiringTooltip}
            />
            <AnimatedMetricCard
              icon={Calendar}
              value={executiveStats.interviewsThisWeek || 0}
              label="Interviews This Week"
              color="#C5B9D6"
              onClick={() => navigate('/interview-hub')}
              tooltipItems={getInterviewsThisWeekTooltip}
            />
            <AnimatedMetricCard
              icon={CheckCircle}
              value={executiveStats.submissionsThisWeek || 0}
              label="Submissions This Week"
              color="#F4C2A8"
              tooltipItems={getSubmissionsThisWeekTooltip}
            />
            <AnimatedMetricCard
              icon={Users}
              value={executiveStats.activeCandidates || 0}
              label="Active Candidates"
              color="#E8B4B8"
              tooltipItems={getActiveCandidatesTooltip}
            />
            <AnimatedMetricCard
              icon={TrendingUp}
              value={executiveStats.outreachThisWeek || 0}
              label="Team Outreach"
              color="#7AA2F7"
              trend={executiveStats.replyRate !== null && executiveStats.replyRate >= 35 ? 'up' : executiveStats.repliesReceived > 0 ? 'up' : 'down'}
              trendValue={executiveStats.replyRate !== null ? `${executiveStats.replyRate}% reply` : `${executiveStats.repliesReceived || 0} replies`}
              tooltipItems={getTeamOutreachTooltip}
            />
            <AnimatedMetricCard
              icon={TrendingUpIcon}
              value={weeklyOutreachByPosition.length}
              label="Positions Outreach This Week"
              color="#F7A9BA"
              tooltipItems={
                weeklyOutreachByPosition.length > 0 ?
                  weeklyOutreachByPosition.map(pos => ({
                    primary: pos.title,
                    badge: `${pos.count} outreach`,
                  })) : [{ primary: "No outreach for any position this week." }]
              }
            />
          </div>

          {/* Quick Pipeline Funnel */}
          <div className="chart-card">
            <h2><Briefcase size={24} /> Team Pipeline Overview</h2>
            <PipelineFunnel
              data={Object.values(pipelineMetrics).reduce((acc, pos) => {
                Object.entries(pos.stages).forEach(([stage, count]) => {
                  const existing = acc.find(s => s.stage === stage);
                  if (existing) existing.count += count;
                  else acc.push({ stage, count });
                });
                return acc;
              }, [])}
              stages={['Screening', 'Submit to Client', 'Interview 1', 'Interview 2', 'Interview 3', 'Offer', 'Hired']}
            />
          </div>
        </div>
      )}

      {activeTab === 'performance' && (
        <div>
          <PerformanceTab
            stats={executiveStats}
            historicalData={historicalData}
            roleHealth={roleHealth}
            groupedRolesByHealth={groupedRolesByHealth} // Pass new prop
          />
        </div>
      )}

      {activeTab === 'team' && (
        <div>
          <TeamMetricsTab recruiterStats={recruiterStats} />
        </div>
      )}

      {activeTab === 'operations' && (
        <div>
          <DailyOperationsTab callsData={callsData} interviewsData={interviewsData} />
        </div>
      )}

      {activeTab === 'pipeline' && (
        <div>
          <PipelineDeepDiveTab
            pipelineMetrics={pipelineMetrics}
            roleHealth={roleHealth}
            navigate={navigate}
          />
        </div>
      )}
    </div>
  );
}

export default Dashboard;
